  const duplicateCounts = new Map(emailDuplicates.groups.map(group => [group[0]?.id, Math.max(0, group.length - 1)]).filter(([id]) => Boolean(id)) as Array<[string, number]>);
  const base = emailLog.filter(item => !duplicateCopyIds.has(item.id));
  const pending = base.filter(item => item.review_status === 'pending_review');
  const unlinked = pending.filter(item => emailLogKind(item) === 'unlinked');
  const uncertain = pending.filter(item => emailLogKind(item) === 'uncertain');
  const exact = pending.filter(item => emailLogKind(item) === 'exact');
  const applied = base.filter(item => item.review_status === 'applied' || item.review_status === 'ignored');
  const visible = emailLogFilter === 'review' ? pending : emailLogFilter === 'applied' ? applied : base;
