      options.innerHTML = matches.length ? matches.map(job => `<button type="button" data-review-job-choice="${job.id}" class="block w-full rounded px-2 py-2 text-left text-xs text-gray-900 hover:bg-gray-50">${escape(jobLabel(job))}</button>`).join('') : '<p class="px-2 py-2 text-xs text-gray-500">Ничего не найдено</p>';
