  bindJobActions(board);
  board.querySelectorAll<HTMLElement>('[data-open-archive-email]').forEach(button => button.onclick = () => void focusArchiveEmailForJob(button.dataset.openArchiveEmail!).catch(error => show(error.message, true)));
  board.querySelectorAll<HTMLButtonElement>('[data-archive-reason-toggle]').forEach(button => button.onclick = () => void moveArchiveEmailReview(button.dataset.archiveReasonToggle!, button.dataset.archiveReasonNext as 'email_exact' | 'email_review').catch(error => show(error.message, true)));
