  const dialog = $('#imap-settings-dialog') as HTMLDialogElement; const form = $('#imap-settings-form') as HTMLFormElement; const saveState = $('#imap-save-state'); let saveTimer: number | undefined; let saving = false; let saveAgain = false;
  const saveSettings = async () => { if (saving) { saveAgain = true; return; } saving = true; saveState.textContent = 'Сохраняем…'; try { await api('/api/settings/imap', { method: 'PUT', body: JSON.stringify(imapFormPayload()) }); const password = $('#imap-password') as HTMLInputElement; if (password.value) password.value = ''; saveState.textContent = 'Сохранено'; } catch (error) { saveState.textContent = (error as Error).message; saveState.classList.add('text-red-700'); } finally { saving = false; if (saveAgain) { saveAgain = false; void saveSettings(); } } };
