  dimensionOptions?.parentElement?.nextElementSibling?.insertAdjacentHTML('beforeend', options('languages', 'Язык объявления', sankeyFilterCatalog.languages.map(code => ({ id: code, label: code === '__unknown__' ? 'Не определён' : languageFilterLabel(code), color: '#7c3aed' }))));
